local additions={{["aliases"]={"Marshal Marris"},["category"]="figures",["fields"]={["context"]="Marshal Marris directs pressure against the Blackrock encampments around Stonewatch. His proposed answer to their advance is a supply war: deny an army the provisions and weapons that sustain its strength."},["gate"]="HISTORICAL",["id"]="npc-382",["kind"]="figure",["npcIDs"]={382},["questSourceProofs"]={{["atomIDs"]={"98387:description:1-208","98387:objective:1-51"},["minimumStage"]=4,["questID"]=98387,["sourceHash"]="9d9c62830e54f0af1760d23382efcd7e1c20cec117e5cf8449bfc6ed054820e2"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/98387",["title"]="Marshal Marris"},{["aliases"]={"Deputy Feldon"},["category"]="figures",["fields"]={["context"]="Deputy Feldon reads the gnolls' proximity to Lakeshire as a warning of greater boldness to come. He favors a display against their thrashers, using their collars as trophies intended to deter further encroachment."},["gate"]="HISTORICAL",["id"]="npc-1070",["kind"]="figure",["npcIDs"]={1070},["questSourceProofs"]={{["atomIDs"]={"98407:description:1-195","98407:objective:1-67"},["minimumStage"]=4,["questID"]=98407,["sourceHash"]="2b25e1347ee8a847a7fbb7f90c8b964948cf97368592d52d5e5668e4acbf2344"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/98407",["title"]="Deputy Feldon"},{["aliases"]={"Maxan Anvol"},["category"]="figures",["fields"]={["context"]="Maxan Anvol arranges holy candles for Father Gavin's mountain refuge. In describing the priest, he emphasizes care for travelers and healing over the Argent Dawn's more martial work."},["gate"]="HISTORICAL",["id"]="npc-1226",["kind"]="figure",["npcIDs"]={1226},["questSourceProofs"]={{["atomIDs"]={"99158:description:1-201","99158:objective:1-54"},["minimumStage"]=4,["questID"]