:objective:1-51"},["minimumStage"]=4,["questID"]=99161,["sourceHash"]="9dcc7b2c97ca2b54f9c2189266bdff930528e9a0741c5ebc695fe123152b195b"},{["atomIDs"]={"99162:description:1-200","99162:objective:1-60"},["minimumStage"]=4,["questID"]=99162,["sourceHash"]="522fd4c9679e9aa39266caf330b5f03c88470d80881c9b91c85fc44f25b965f3"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/99158",["title"]="Father Gavin"},{["aliases"]={"Quarrymaster Thesten"},["category"]="figures",["fields"]={["context"]="Quarrymaster Thesten is responsible for Gol'Bolar's blasting powder. An empty keg in trogg hands exposes a dangerous loss whose recovery he wants accomplished quickly and quietly."},["gate"]="HISTORICAL",["id"]="npc-1256",["kind"]="figure",["npcIDs"]={1256},["questSourceProofs"]={{["atomIDs"]={"95213:description:1-202","95213:objective:1-76"},["minimumStage"]=4,["questID"]=95213,["sourceHash"]="de4a06c040bc03b6d5c0d3704c523443e812587729537d9f957eedcf78da9fb6"},{["atomIDs"]={"95214:description:1-164","95214:objective:1-69"},["minimumStage"]=4,["questID"]=95214,["sourceHash"]="6c6f1eb6b05661020115f49654bc0cca3aaabd4fb03907021170ece5a35ca861"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/95213",["title"]="Quarrymaster Thesten"},{["aliases"]={"Rudra Amberstill"},["category"]="figures",["fields"]={["context"]="Rudra Amberstill prepares saddles for rams joining the Alterac expedition. Her demand for pristine leopard pelts connects the ranch's everyday work with the cold endured by riders farther afield."},["gate"]="HISTORICAL",["id"]="npc-1265",["kind"]="figure",["npcIDs"]={1265},["questSourceProofs"]={{["atomIDs"]={"95212:description:1-207","95212:objective:1-64"},["minimumStage"]=4,["questID"]=95212,["sourceHash"]="890e1baef75d081a96414439507d4259aa89bc47d485f3be6863c5c64f5ecd9b"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/95212",["title"]="Rudra Amberstill"},{["aliases"]={"Beldin Steelgrill"},["category"]="figures",["fields"]={["context"]="Beldin Steelgrill sends a visitor to investigate a campfire overlooking Gol'Bolar Quarry. He leaves room for a friendly explanation before assuming that a stranger in the hills is an enemy."},["gate"]="HISTORICAL",["id"]="npc-1376",["kind"]="figure",["npcIDs"]={1376},["questSourceProofs"]={{["atomIDs"]={"96408:description:1-179","96408:objective:1-66"},["minimumStage"]=4,["questID"]=96408,["sourceHash"]="a75668f7265cefdd08e9f2ef9c68c0b2bb6a48c39da3632013a455c5156f1885"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/96408",["title"]="Beldin Steelgrill"},{["aliases"]={"Deathguard Linnea"},["category"]="figures",["fields"]={["context"]="Deathguard Linnea treats Riptear's appearance in eastern Tirisfal as both a combat threat and a failure she cannot explain. She calls for discretion because an abomination should not have crossed the Bulwark unnoticed."},["gate"]="HISTORICAL",["id"]="npc-1495",["kind"]="figure",["npcIDs"]={1495},["questSourceProofs"]={{["atomIDs"]={"99156:description:1-193","99156:objective:1-63"},["minimumStage"]=4,["questID"]=99156,["sourceHash"]="c631ea3a84eca5e336ce4b2953d5e071402cb5c8f999f5fab2d1df768c9cf361"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/99156",["title"]="Deathguard Linnea"},{["aliases"]={"Executor Zygand"},["category"]="figures",["fields"]={["context"]="Executor Zygand demands punctual reports and obedience from his Deathguards. He turns their failures into assignments for an outsider, mixing administrative impatience with an undisguised appetite for punishment."},["gate"]="HISTORICAL",["id"]="npc-1515",["kind"]="figure",["npcIDs"]={1515},["questSourceProofs"]={{["atomIDs"]={"99134:description:1-172","99134:objective:1-53"},["minimumStage"]=4,["questID"]=99134,["sourceHash"]="f3cea7ac09c8d0a20f7f8b5fa8135902b3d1accb865c96ca926053c178f3660e"},{["atomIDs"]={"99141:description:1-191","99141:objective:1-68"},["minimumStage"]=4,["questID"]=99141,["sourceHash"]="5c0b74b366fc3ce116a643987dabc4320a42188e6903f3b067e01b2cd2f4d769"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/99134",["title"]="Executor Zygand"},{["aliases"]={"Shadow Priest Sarvis"},["category"]="figures",["fields"]={["context"]="Shadow Priest Sarvis forwards a Light-touched scroll to a newly risen paladin. His discomfort with the recipient's calling colors the errand to Aramis Hammerhand without preventing him from delivering it."},["gate"]="HISTORICAL",["id"]="npc-1569",["kind"]="figure",["npcIDs"]={1569},["questSourceProofs"]={{["atomIDs"]={"98601:description:1-243","98601:objective:1-64","98601:completion:1-88"},["minimumStage"]=4,["questID"]=98601,["sourceHash"]="2e17a1848c0e976d83749b41a1ab7e70addecf781ccbc711ca6dbdf32ae5cd08"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/98601",["title"]="Shadow Priest Sarvis"},{["aliases"]={"Executor Arren"},["category"]="figures",["fields"]={["context"]="Executor Arren asks that an unfamiliar adventurer near Brill be investigated. His suspicion brings the traveler to Eleanor Shackleton, whose business there is camping rather than the Scarlet Crusade."},["gate"]="HISTORICAL",["id"]="npc-1570",["kind"]="figure",["npcIDs"]={1570},["questSourceProofs"]={{["atomIDs"]={"96656:description:1-191","96656:objective:1-57"},["minimumStage"]=4,["questID"]=96656,["sourceHash"]="4f772dea1bff2675da4ff489eda6577635d02812a66b0137466e0c448ef64f09"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/96656",["title"]="Executor Arren"},{["aliases"]={"Deathguard Terrence"},["category"]="figures",["fields"]={["context"]="Deathguard Terrence notices two Forsaken emissaries of the Argent Dawn passing through Tirisfal. Their shared condition does not allay his unease about outside agents investigating the region without supervision."},["gate"]="HISTORICAL",["id"]="npc-1738",["kind"]="figure",["npcIDs"]={1738},["questSourceProofs"]={{["atomIDs"]={"96895:description:1-206","96895:objective:1-72"},["minimumStage"]=4,["questID"]=96895,["sourceHash"]="b2bc937c2a745cad049a1b0b5f7a73dab875558bcdc1118f65089f8d9dcc3a1a"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/96895",["title"]="Deathguard Terrence"},{["aliases"]={"Apothecary Renferrel"},["category"]="figures",["fields"]={["context"]="Apothecary Renferrel treats Quinn Yorick's recovery as an alchemical problem. Although dismissive when a potion fails, he is willing to test murloc eyes alongside the hearts on which he insists."},["gate"]="HISTORICAL",["id"]="npc-1937",["kind"]="figure",["npcIDs"]={1937},["questSourceProofs"]={{["atomIDs"]={"91920:description:1-188","91920:objective:1-66"},["minimumStage"]=4,["questID"]=91920,["sourceHash"]="68598697fdeda6adcc123a3ccc22e70120c4d987533b3e029474a898e9aae4c2"},{["atomIDs"]={"91921:description:1-150","91921:objective:1-45"},["minimumStage"]=4,["questID"]=91921,["sourceHash"]="201c8524f0a384dd015ba5cd4d149e3a292f72b98fbf023328e2269d49b9a0ed"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/91920",["title"]="Apothecary Renferrel"},{["aliases"]={"Quinn Yorick"},["category"]="figures",["fields"]={["context"]="Quinn Yorick waits for strength enough to travel from the Ivar Patch. When Renferrel's first potion makes no perceptible difference, Quinn proposes a different ingredient rather than accepting a second death without argument."},["gate"]="HISTORICAL",["id"]="npc-1951",["kind"]="figure",["npcIDs"]={1951},["questSourceProofs"]={{["atomIDs"]={"91920:description:1-188","91920:objective:1-66"},["minimumStage"]=4,["questID"]=91920,["sourceHash"]="68598697fdeda6adcc123a3ccc22e70120c4d987533b3e029474a898e9aae4c2"},{["atomIDs"]={"91921:description:1-150","91921:objective:1-45"},["minimumStage"]=4,["questID"]=91921,["sourceHash"]="201c8524f0a384dd015ba5cd4d149e3a292f72b98fbf023328e2269d49b9a0ed"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/91920",["title"]="Quinn Yorick"},{["aliases"]={"Master Apothecary Faranell"},["category"]="figures",["fields"]={["context"]="Master Apothecary Faranell recognizes the recovered head of the former Grand Marshal Othmar. He treats both memory and resistance as material for experiment, turning reassembly into an attempt to compel service to Sylvanas."},["gate"]="HISTORICAL",["id"]="npc-2055",["kind"]="figure",["npcIDs"]={2055},["questSourceProofs"]={{["atomIDs"]={"97288:description:1-152","97288:objective:1-76"},["minimumStage"]=4,["questID"]=97288,["sourceHash"]="2d961a808ebd593fa224f3135d3b9bd76e3b6035fe45aede6999c7122bd32f02"},{["atomIDs"]={"97289:description:1-249","97289:objective:1-63"},["minimumStage"]=4,["questID"]=97289,["sourceHash"]="21a925a59fc15b886d6efd2bbf27892462672287390739c8a963c19cee674373"},{["atomIDs"]={"97290:description:1-146","97290:objective:1-55"},["minimumStage"]=4,["questID"]=97290,["sourceHash"]="51d3f5763c9e1a730206d40a31d35c954b89dbca8f62953eede59cd00d2cee50"},{["atomIDs"]={"97291:description:1-231","97291:objective:1-60"},["minimumStage"]=4,["questID"]=97291,["sourceHash"]="53f598b1cdad319011358e5f9c09967f7fed9b4410b2e821ba3fbc21212502ed"},{["atomIDs"]={"97292:description:1-187","97292:objective:1-67"},["minimumStage"]=4,["questID"]=97292,["sourceHash"]="2a7b08cf532a4fe1cf175d166f3e0973074098fe2e42a067c214e5f644e3d87c"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/97288",["title"]="Master Apothecary Faranell"},{["aliases"]={"Shadow Priest Allister"},["category"]="figures",["fields"]={["context"]="Shadow Priest Allister believes Dalaran relics are moving into Silverpine along the Ambermill roads. His answer expands from taking pendants to attacking the wizards and watchers he holds responsible for the traffic."},["gate"]="HISTORICAL",["id"]="npc-2121",["kind"]="figure",["npcIDs"]={2121},["questSourceProofs"]={{["atomIDs"]={"95981:description:1-211","95981:objective:1-74"},["minimumStage"]=4,["questID"]=95981,["sourceHash"]="3fe8062910fcfcc12d22ff4daa22e473be2e80e0752a200f713ecb0807e6da4b"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/95981",["title"]="Shadow Priest Allister"},{["aliases"]={"Carolai Anise"},["category"]="figures",["fields"]={["context"]="Carolai Anise has customers for Shadowvale's Whispering Elixir. She recounts its restricted, unsettling reputation, but treats the possibility of profit more concretely than the forest's rumors of a curse."},["gate"]="HISTORICAL",["id"]="npc-2132",["kind"]="figure",["npcIDs"]={2132},["questSourceProofs"]={{["atomIDs"]={"95314:description:1-187","95314:objective:1-82"},["minimumStage"]=4,["questID"]=95314,["sourceHash"]="477de7f18b673aaad5960f7d0f942b27c8f44f6ca580187d0285c19fd784923c"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/95314",["title"]="Carolai Anise"},{["aliases"]={"Chief Hawkwind"},["category"]="figures",["fields"]={["context"]="Chief Hawkwind remembers Kaga Wildhoof's earlier aid. He sends supplies to her camp outside Bloodhoof Village as repayment, despite her having sought no compensation."},["gate"]="HISTORICAL",["id"]="npc-2981",["kind"]="figure",["npcIDs"]={2981},["questSourceProofs"]={{["atomIDs"]={"96659:description:1-174","96659:objective:1-50"},["minimumStage"]=4,["questID"]=96659,["sourceHash"]="b136eebeafa21b45c2d38e1a618285609cc2c57098a60d0bc07684f254d2e08d"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/96659",["title"]="Chief Hawkwind"},{["aliases"]={"Seer Graytongue"},["category"]="figures",["fields"]={["context"]="Seer Graytongue teaches respect for An'she and Mu'sha alongside the spirits of the world. His incense errand makes that teaching practical, requiring care for the offering on the journey to the twins' shrine."},["gate"]="HISTORICAL",["id"]="npc-2982",["kind"]="figure",["npcIDs"]={2982},["questSourceProofs"]={{["atomIDs"]={"95805:description:1-201","95805:objective:1-83"},["minimumStage"]=4,["questID"]=95805,["sourceHash"]="04e4ebce71b1a54d52c763c64c2a8d987237658f81fd446c50d3dfcc838221a8"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/95805",["title"]="Seer Graytongue"},{["aliases"]={"Baine Bloodhoof"},["category"]="figures",["fields"]={["context"]="Baine Bloodhoof leads Bloodhoof Village and answers the warning of a centaur incursion. He calls for the raiding party to be stopped before it threatens the settlement, then refers recognized service to Cairne in Thunder Bluff."},["gate"]="HISTORICAL",["id"]="npc-2993",["kind"]="figure",["npcIDs"]={2993},["questSourceProofs"]={{["atomIDs"]={"99080:description:1-234","99080:objective:1-84"},["minimumStage"]=4,