uestSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/99082",["title"]="Cairne Bloodhoof"},{["aliases"]={"Krang Stonehoof"},["category"]="figures",["fields"]={["context"]="The recorder identifies this arena teacher as Krang Stonehoof. His sparring invitation extends beyond warriors to any willing learner, although the quest objective independently names Tang Stonehoof and leaves that field conflict unresolved."},["gate"]="HISTORICAL",["id"]="npc-3063",["kind"]="figure",["npcIDs"]={3063},["questSourceProofs"]={{["atomIDs"]={"99108:description:1-200","99108:objective:1-82"},["minimumStage"]=4,["questID"]=99108,["sourceHash"]="e21c4c30145bed55c0bbeed002df5e8486a4303e67aaf84f01eab97b6e2fa844"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/99108",["title"]="Krang Stonehoof"},{["aliases"]={"Yaw Sharpmane"},["category"]="figures",["fields"]={["context"]="Yaw Sharpmane warns of Chakuyak, an aggressive prairie wolf west of Stonebull Lake. He asks for her pelt as evidence that a danger to arriving travelers has been ended."},["gate"]="HISTORICAL",["id"]="npc-3065",["kind"]="figure",["npcIDs"]={3065},["questSourceProofs"]={{["atomIDs"]={"96130:description:1-192","96130:objective:1-55"},["minimumStage"]=4,["questID"]=96130,["sourceHash"]="0c6d7f6190dddd787fef5263b22b79103c198096e41518ce0cd8c72faab2e29e"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/96130",["title"]="Yaw Sharpmane"},{["aliases"]={"Orgnil Soulscar"},["category"]="figures",["fields"]={["context"]="Orgnil Soulscar acts on a scout's report of a sea giant on Durotar's northern coast. He does not claim to know whether the naga brought it deliberately; the immediate danger is enough to warrant action."},["gate"]="HISTORICAL",["id"]="npc-3142",["kind"]="figure",["npcIDs"]={3142},["questSourceProofs"]={{["atomIDs"]={"99052:description:1-208","99052:objective:1-64"},["minimumStage"]=4,["questID"]=99052,["sourceHash"]="6ede3c98e70aec5d708051846e60341e2ea6dbd2067d69b480540d9ca71ff130"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/99052",["title"]="Orgnil Soulscar"},{["aliases"]={"Gornek"},["category"]="figures",["fields"]={["context"]="Gornek puts new recruits to work recovering abandoned training weapons. The errand serves two needs at once: judging the recruit's resourcefulness and replenishing Kzan's dwindling stock."},["gate"]="HISTORICAL",["id"]="npc-3143",["kind"]="figure",["npcIDs"]={3143},["questSourceProofs"]={{["atomIDs"]={"97279:description:1-200","97279:objective:1-66"},["minimumStage"]=4,["questID"]=97279,["sourceHash"]="91d6f696c073d3a1777e7f9ef0710c039e6604d331ef6e8006da2e89bcdcfc4b"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/97279",["title"]="Gornek"},{["aliases"]={"Kzan Thornslash"},["category"]="figures",["fields"]={["context"]="Kzan Thornslash repairs weapons returned from Durotar's training grounds. Failed recruits have left useful equipment behind, and his work prepares that salvage for those still arriving at the Den."},["gate"]="HISTORICAL",["id"]="npc-3159",["kind"]="figure",["npcIDs"]={3159},["questSourceProofs"]={{["atomIDs"]={"97279:description:1-200","97279:objective:1-66"},["minimumStage"]=4,["questID"]=97279,["sourceHash"]="91d6f696c073d3a1777e7f9ef0710c039e6604d331ef6e8006da2e89bcdcfc4b"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/97279",["title"]="Kzan Thornslash"},{["aliases"]={"Master Gadrin"},["category"]="figures",["fields"]={["context"]="Master Gadrin receives the loa idols recovered from the Echo Isles. He describes the Darkspear's relationship with their loa as one of reverence and gratitude, making recovery a duty beyond material value."},["gate"]="HISTORICAL",["id"]="npc-3188",["kind"]="figure",["npcIDs"]={3188},["questSourceProofs"]={{["atomIDs"]={"97225:description:1-206","97225:objective:1-83"},["minimumStage"]=4,["questID"]=97225,["sourceHash"]="a595ccf856337cbf48042ec90ae6957d02dfc439ab90dfe04f2b479e6ce8fe2b"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/97225",["title"]="Master Gadrin"},{["aliases"]={"Cook Torka"},["category"]="figures",["fields"]={["context"]="Cook Torka teaches the rudiments of a cooking-based campsite at Razor Hill. For the troops' table, the cook also looks beyond the usual savory fare to prickly pears, saving their seeds for future planting."},["gate"]="HISTORICAL",["id"]="npc-3191",["kind"]="figure",["npcIDs"]={3191},["questSourceProofs"]={{["atomIDs"]={"96655:description:1-148","96655:objective:1-59"},["minimumStage"]=4,["questID"]=96655,["sourceHash"]="f3cca62149bc0478a59855e029df9e491997f0dd5071dd0051b0af6e64eaf395"},{["atomIDs"]={"96825:description:1-210","96825:objective:1-55"},["minimumStage"]=4,["questID"]=96825,["sourceHash"]="8d2671fe9fcb3683907fba5c7c3259e1eeea6d9d33ab39b13d3df0e1b54c7806"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/96655",["title"]="Cook Torka"},{["aliases"]={"Vel'rin Fang"},["category"]="figures",["fields"]={["context"]="Vel'rin Fang has noticed fewer travelers from Razor Hill. Reports of spider nests along the road prompt a request that northbound travelers clear some of the danger and notify Gar'thok."},["gate"]="HISTORICAL",["id"]="npc-3194",["kind"]="figure",["npcIDs"]={3194},["questSourceProofs"]={{["atomIDs"]={"96821:description:1-187","96821:objective:1-90"},["minimumStage"]=4,["questID"]=96821,["sourceHash"]="e368082ed94f03b71128cc8469c81adabda0a377bd330daf19ff553defe39bc5"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/96821",["title"]="Vel'rin Fang"},{["aliases"]={"Brave Wildrunner"},["category"]="figures",["fields"]={["context"]="Brave Wildrunner keeps watch over Bloodhoof Village while seeking news of the missing Longwalker Malah. Her report makes him the first link between a lost scout and the warning that must reach Baine."},["gate"]="HISTORICAL",["id"]="npc-3222",["kind"]="figure",["npcIDs"]={3222},["questSourceProofs"]={{["atomIDs"]={"99079:description:1-217","99079:objective:1-64"},["minimumStage"]=4,["questID"]=99079,["sourceHash"]="6bdd200ead7e2c1e38b190fd5a4a631de9182f9a204f1827fb82c81eb36e6fce"},{["atomIDs"]={"99081:description:1-199","99081:objective:1-59"},["minimumStage"]=4,["questID"]=99081,["sourceHash"]="083683ff96e126f17665334410d0bf364720e08718fe27ee9e92b1f6c89e3fd7"},{["atomIDs"]={"99101:description:1-196","99101:objective:1-48"},["minimumStage"]=4,["questID"]=99101,["sourceHash"]="6749c1e962d37088ba1f05503032340253f019b9b4ccd590b6bb195eef93a646"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/99079",["title"]="Brave Wildrunner"},{["aliases"]={"Master Vornal"},["category"]="figures",["fields"]={["context"]="Master Vornal asks for sacred idols left behind during the flight from the Echo Isles. He also receives news of Pal'juh's rescue, balancing regard for a promising hunter with concern over her solitary recklessness."},["gate"]="HISTORICAL",["id"]="npc-3304",["kind"]="figure",["npcIDs"]={3304},["questSourceProofs"]={{["atomIDs"]={"97225:description:1-206","97225:objective:1-83"},["minimumStage"]=4,["questID"]=97225,["sourceHash"]="a595ccf856337cbf48042ec90ae6957d02dfc439ab90dfe04f2b479e6ce8fe2b"},{["atomIDs"]={"99123:description:1-137","99123:objective:1-63"},["minimumStage"]=4,["questID"]=99123,["sourceHash"]="c6834777f67aa6516af6d2362159033285d2a8401282548bc5cae2451a21b08f"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/97225",["title"]="Master Vornal"},{["aliases"]={"Gazlowe"},["category"]="figures",["fields"]={["context"]="Gazlowe has offered a bounty on Bruuz, the shark frightening Ratchet's dock crews. The reward serves the harbor's working life: sailors cannot do their jobs while the water beside the dock remains unsafe."},["gate"]="HISTORICAL",["id"]="npc-3391",["kind"]="figure",["npcIDs"]={3391},["questSourceProofs"]={{["atomIDs"]={"92706:description:1-186","92706:objective:1-54"},["minimumStage"]=4,["questID"]=92706,["sourceHash"]="1bcc48b41c9f842cc0940b051f626ff7fc82f7b74d7fc7aa626db8648d1255d1"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/92706",["title"]="Gazlowe"},{["aliases"]={"Mankrik"},["category"]="figures",["fields"]={["context"]="Mankrik remembers his wife as Olgra and seeks her missing polished-bone adornments. He wants her own work placed at the memorial he is building, preserving identity within the account of her loss."},["gate"]="HISTORICAL",["id"]="npc-3432",["kind"]="figure",["npcIDs"]={3432},["questSourceProofs"]={{["atomIDs"]={"95774:description:1-191","95774:objective:1-68"},["minimumStage"]=4,["questID"]=95774,["sourceHash"]="544495f413206621b5b7d08e5fc8e5a353dd62bea8c2ea3b583110656fbfcffc"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/95774",["title"]="Mankrik"},{["aliases"]={"Sentinel Arynia Cloudsbreak"},["category"]="figures",["fields"]={["context"]="Sentinel Arynia Cloudsbreak investigates corruption found in harpy belongings. She has a suspicion about its source, but asks for the leaders' amulets before treating the darkened belts as conclusive evidence."},["gate"]="HISTORICAL",["id"]="npc-3519",["kind"]="figure",["npcIDs"]={3519},["questSourceProofs"]={{["atomIDs"]={"98392:description:1-193","98392:objective:1-98"},["minimumStage"]=4,["questID"]=98392,["sourceHash"]="7477ef03977a3a83e9b2ec4f8863644f300acedb6dbac68db924ea210d318f2f"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/98392",["title"]="Sentinel Arynia Cloudsbreak"},{["aliases"]={"Ott"},["category"]="figures",["fields"]={["context"]="Ott sells practical weapons at Tarren Mill without seeking reputation or ceremony. Trevan's recommendation offers him an unusual commission, allowing the quiet quality of his ordinary work to become a masterwork."},["gate"]="HISTORICAL",["id"]="npc-3539",["kind"]="figure",["npcIDs"]={3539},["questSourceProofs"]={{["atomIDs"]={"95111:description:1-196","95111:objective:1-75"},["minimumStage"]=4,["questID"]=95111,["sourceHash"]="5b5cbbd820646c3cacb35a36ee8dc7833f38c67d565a4ad806c8d76f11ac1b13"},{["atomIDs"]={"95125:description:1-144","95125:objective:1-43"},["minimumStage"]=4,["questID"]=95125,["sourceHash"]="7c1c48e96871339bd190ae32f68ba8779e5a8889fe794f022163c9b02e37c420"},{["atomIDs"]={"95126:description:1-168","95126:objective:1-51"},["minimumStage"]=4,["questID"]=95126,["sourceHash"]="d3dd7feed3b68dcc87ef5496316f0c4589ef01dd72ac678b6ae40880d1a0c954"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/95111",["title"]="Ott"},{["aliases"]={"Shelene Rhobart"},["category"]="figures",["fields"]={["context"]="Shelene Rhobart explains the Forsaken's need to replace damaged skin with hides. Her request distinguishes thin bat membranes, heavier darkhound hides and murloc skin according to their possible uses."},["gate"]="HISTORICAL",["id"]="npc-3549",["kind"]="figure",["npcIDs"]={3549},["questSourceProofs"]={{["atomIDs"]={"97558:description:1-209","97558:objective:1-106"},["minimumStage"]=4,["questID"]=97558,["sourceHash"]="8770a2c912cac20182b4b6f485d000a20f15b04ebc12c11d24a31295dafc7aef"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/97558",["title"]="Shelene Rhobart"},{["aliases"]={"Brom Killian"},["category"]="figures",["fields"]={["context"]="Brom Killian supplies the mining branch of Eleanor Shackleton's camping referral. His Lodestone instruction includes the conditions for using camp furnishings outside town around an established fire."},["gate"]="HISTORICAL",["id"]="npc-4598",["kind"]="figure",["npcIDs"]={4598},["questSourceProofs"]={{["atomIDs"]={"97959:description:1-166","97959:objective:1-57"},["minimumStage"]=4,["questID"]=97959,["sourceHash"]="880f5dfea340767037b0caf375c46055db7df16693712cfbb3873d2d2dac5b68"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/97959",["title"]="Brom Killian"},{["aliases"]={"Kamari"},["category"]="figures",["fields"]={["context"]="Kamari provides hides for Orgrimmar's growing buildings. Lizard skin from Thunder Ridge may be too thick for armor yet useful for walls and roofs, giving leatherwork a civic use beyond equipping adventurers."},["gate"]="HISTORICAL",["id"]="npc-5811",["kind"]="figure",["npcIDs"]={5811},["questSourceProofs"]={{["atomIDs"]={"96875:description:1-204","96875:objective:1-84"},["minimumStage"]=4,["questID"]=96875,["sourceHash"]="29943c883bc9d18477d5ca5c3792bd2474b93b53d3cd428c1ee9315833543da8"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUB