ind"]="figure",["npcIDs"]={7161},["questSourceProofs"]={{["atomIDs"]={"97253:description:1-177","97253:objective:1-73"},["minimumStage"]=4,["questID"]=97253,["sourceHash"]="e52739c04ff7df7d76c83d5abf3dfc41cc89170611267aab17b589e00f8dbd2a"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/97253",["title"]="Wrenix the Wretched"},{["aliases"]={"Alessandro Luca"},["category"]="figures",["fields"]={["context"]="Alessandro Luca needs a potion carried quickly to Doctor Martin Felben. He explains that his knees cannot sustain the run, making a short errand across Undercity's canal an urgent reliance on another traveler."},["gate"]="HISTORICAL",["id"]="npc-7683",["kind"]="figure",["npcIDs"]={7683},["questSourceProofs"]={{["atomIDs"]={"97891:description:1-241","97891:objective:1-77"},["minimumStage"]=4,["questID"]=97891,["sourceHash"]="69c6c2241167b250bd755afdb3bd5bcf315bea25778a7c59928c7f7c832126b6"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/97891",["title"]="Alessandro Luca"},{["aliases"]={"Oran Snakewrithe"},["category"]="figures",["fields"]={["context"]="Oran Snakewrithe receives a surviving crest of Lordaeron with an eye for authenticity. Once satisfied, he treats it as a piece of their homeland's damaged history to be preserved carefully."},["gate"]="HISTORICAL",["id"]="npc-7825",["kind"]="figure",["npcIDs"]={7825},["questSourceProofs"]={{["atomIDs"]={"95204:description:1-169","95204:objective:1-66"},["minimumStage"]=4,["questID"]=95204,["sourceHash"]="e0af53ec87562740c0fdb980e0852692488a86f8c05536225f66f2171a9fd0a6"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/95204",["title"]="Oran Snakewrithe"},{["aliases"]={"Xar'Ti"},["category"]="figures",["fields"]={["context"]="Xar'Ti raises raptors as allies for Sen'jin Village. The dangerous Bloodtalon Matriarch must be stopped, but her eggs offer a way to retain the bloodline under the tribe's care."},["gate"]="HISTORICAL",["id"]="npc-7953",["kind"]="figure",["npcIDs"]={7953},["questSourceProofs"]={{["atomIDs"]={"97223:description:1-209","97223:objective:1-66"},["minimumStage"]=4,["questID"]=97223,["sourceHash"]="2df4d86d4e4ed59f30108a47e902bf8328f16c249bcb22cbf1f8265cf7ee39d1"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/97223",["title"]="Xar'Ti"},{["aliases"]={"Gretta Ganter"},["category"]="figures",["fields"]={["context"]="Gretta Ganter wants back the sack of fish stolen by Frosthowl. Her urgency is domestic and specific: Paxton has already spent days fishing the frozen lake, and replacing the catch would prolong that ordeal."},["gate"]="HISTORICAL",["id"]="npc-8508",["kind"]="figure",["npcIDs"]={8508},["questSourceProofs"]={{["atomIDs"]={"98326:description:1-194","98326:objective:1-63"},["minimumStage"]=4,["questID"]=98326,["sourceHash"]="87d50963ffe3aa7c95e31c3f90fb4199dc043a954ca5329f0081061ba9d9f825"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/98326",["title"]="Gretta Ganter"},{["aliases"]={"Lady Sylvanas Windrunner"},["category"]="figures",["fields"]={["context"]="Sylvanas Windrunner receives the head offered by Danitha's paladins as proof of loyalty. Her reply distinguishes belief in Danitha's sincerity from confidence in the order, whose future acceptance she makes conditional on its service."},["gate"]="HISTORICAL",["id"]="npc-10181",["kind"]="figure",["npcIDs"]={10181},["questSourceProofs"]={{["atomIDs"]={"95803:description:1-218","95803:objective:1-65"},["minimumStage"]=4,["questID"]=95803,["sourceHash"]="e7d2ae0036f7021fa8f928a3f93d61d9bbc44f5e6f1a011d4885fe43ff4b6295"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/95803",["title"]="Lady Sylvanas Windrunner"},{["aliases"]={"Junior Apothecary Holland"},["category"]="figures",["fields"]={["context"]="Junior Apothecary Holland cultivates an altered form of doom weed at the Balnir Farmstead. He calls it tomb weed and regards its promise of violent consequences as scientific progress rather than cause for restraint."},["gate"]="HISTORICAL",["id"]="npc-10665",["kind"]="figure",["npcIDs"]={10665},["questSourceProofs"]={{["atomIDs"]={"99142:description:1-193","99142:objective:1-47"},["minimumStage"]=4,["questID"]=99142,["sourceHash"]="0748098441a159e693a4dda7495f6d64dcbaffad43ea26560f69afe547a13e31"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/99142",["title"]="Junior Apothecary Holland"},{["aliases"]={"Theodore Griffs"},["category"]="figures",["fields"]={["context"]="Theodore Griffs studies virulent specimens in the Apothecarium. Witherfang's rumored ability to damage undead flesh interests him as an experiment; preserving access to its venom matters more to him than a successful hunt."},["gate"]="HISTORICAL",["id"]="npc-11835",["kind"]="figure",["npcIDs"]={11835},["questSourceProofs"]={{["atomIDs"]={"95216:description:1-183","95216:objective:1-73"},["minimumStage"]=4,["questID"]=95216,["sourceHash"]="96a4b1058b39c8fe3378bc00b9267b68256d59ec4c70f4c2be70f89e88ce7f17"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/95216",["title"]="Theodore Griffs"},{["aliases"]={"Sulhasa"},["category"]="figures",["fields"]={["context"]="Sulhasa is stranded above the southern Barrens in a tree after a walk from Camp Taurajo. Hyenas and lizards below turn the homeward journey into a plea for help clearing an escape."},["gate"]="HISTORICAL",["id"]="npc-14242",["kind"]="figure",["npcIDs"]={14242},["questSourceProofs"]={{["atomIDs"]={"98093:description:1-200","98093:objective:1-79"},["minimumStage"]=4,["questID"]=98093,["sourceHash"]="b246248ccd0cbd0cb4a5efbe9b74f04a44759be80133390b42b26b7098044312"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/98093",["title"]="Sulhasa"},{["aliases"]={"Aramis Hammerhand"},["category"]="figures",["fields"]={["context"]="Aramis Hammerhand trains Forsaken paladins in Deathknell. He insists that the Light can serve their people despite the pain and distrust surrounding undeath, and asks for trapped Forsaken to be freed as a practical demonstration."},["gate"]="HISTORICAL",["id"]="npc-244808",["kind"]="figure",["npcIDs"]={244808},["questSourceProofs"]={{["atomIDs"]={"90902:description:1-195","90902:objective:1-63","90902:completion:1-101"},["minimumStage"]=4,["questID"]=90902,["sourceHash"]="c951c39f81a4a73be1ef6262e795b63c4c32d95bcd29f55ed662b2666d829e39"},{["atomIDs"]={"91208:description:1-259","91208:objective:1-73","91208:completion:1-147"},["minimumStage"]=4,["questID"]=91208,["sourceHash"]="e09377627c7178ce4a3626a0eaf935105e49640d07331fca29f22ea7afc70886"},{["atomIDs"]={"91209:description:1-202","91209:objective:1-67","91209:completion:1-106"},["minimumStage"]=4,["questID"]=91209,["sourceHash"]="b939cb8b64d1d4f18a23d8a87712bea8124880a49e4c6e8e831d26d2904e21df"},{["atomIDs"]={"98389:description:1-201","98389:objective:1-53"},["minimumStage"]=4,["questID"]=98389,["sourceHash"]="e95eebe587ef1396c3e4449731b4e819939e441e5ddadbaac14dbf1bdf83764d"},{["atomIDs"]={"98601:description:1-243","98601:objective:1-64","98601:completion:1-88"},["minimumStage"]=4,["questID"]=98601,["sourceHash"]="2e17a1848c0e976d83749b41a1ab7e70addecf781ccbc711ca6dbdf32ae5cd08"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/90902",["title"]="Aramis Hammerhand"},{["aliases"]={"Shari Stilwell"},["category"]="figures",["fields"]={["context"]="Shari Stilwell introduces newly risen paladins to the fellowship forming at Bandarion Keep. Her welcome extends beyond instruction to gratitude for Bareth Dawnstone's rescue and an invitation to those seeking guidance."},["gate"]="HISTORICAL",["id"]="npc-246152",["kind"]="figure",["npcIDs"]={246152},["questSourceProofs"]={{["atomIDs"]={"91209:description:1-202","91209:objective:1-67","91209:completion:1-106"},["minimumStage"]=4,["questID"]=91209,["sourceHash"]="b939cb8b64d1d4f18a23d8a87712bea8124880a49e4c6e8e831d26d2904e21df"},{["atomIDs"]={"91282:description:1-227","91282:objective:1-61","91282:completion:1-46"},["minimumStage"]=4,["questID"]=91282,["sourceHash"]="8c3e360bdceec11c0bdce30870409a48a00db32e2b277119245a2b2230c2c718"},{["atomIDs"]={"99144:description:1-203","99144:objective:1-87"},["minimumStage"]=4,["questID"]=99144,["sourceHash"]="3992b05cfe295d5995232c51a9a56131d2f3b96c6a72689fffa09020a4567165"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/91209",["title"]="Shari Stilwell"},{["aliases"]={"Breton Samuels"},["category"]="figures",["fields"]={["context"]="Breton Samuels receives newcomers at Bandarion Keep under the name Tyr's Watch. Rebuilding its fellowship competes with an immediate practical problem: displaced murlocs continue attacking the stronghold."},["gate"]="HISTORICAL",["id"]="npc-246349",["kind"]="figure",["npcIDs"]={246349},["questSourceProofs"]={{["atomIDs"]={"91282:description:1-227","91282:objective:1-61","91282:completion:1-46"},["minimumStage"]=4,["questID"]=91282,["sourceHash"]="8c3e360bdceec11c0bdce30870409a48a00db32e2b277119245a2b2230c2c718"},{["atomIDs"]={"91285:description:1-265","91285:objective:1-76","91285:completion:1-111"},["minimumStage"]=4,["questID"]=91285,["sourceHash"]="e638f014f40e163b95e88c15085d3cfc052bd4bca331904b234ef8a72717ad9f"},{["atomIDs"]={"91294:description:1-268","91294:objective:1-66","91294:completion:1-113"},["minimumStage"]=4,["questID"]=91294,["sourceHash"]="0630c919d46210f712ccbdaaf94dec618adcecdfd98211b8a2f948737a82d4c9"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/91282",["title"]="Breton Samuels"},{["aliases"]={"Danitha Morr"},["category"]="figures",["fields"]={["context"]="Danitha Morr leads the paladins establishing themselves at Bandarion Keep. She connects their work in service, repair and defense with the difficult task of earning trust among Forsaken who remember persecution in the Light's name."},["gate"]="HISTORICAL",["id"]="npc-246378",["kind"]="figure",["npcIDs"]={246378},["questSourceProofs"]={{["atomIDs"]={"91294:description:1-268","91294:objective:1-66","91294:completion:1-113"},["minimumStage"]=4,["questID"]=91294,["sourceHash"]="0630c919d46210f712ccbdaaf94dec618adcecdfd98211b8a2f948737a82d4c9"},{["atomIDs"]={"91317:description:1-282","91317:objective:1-85","91317:completion:1-127"},["minimumStage"]=4,["questID"]=91317,["sourceHash"]="92c5553b2b0aa4e4b86494c3a76572056e250175d39691fef85800ff4adf3863"},{["atomIDs"]={"91858:description:1-241","91858:objective:1-61"},["minimumStage"]=4,["questID"]=91858,["sourceHash"]="d942070c29472e96120c9254390773f26818112b8379230e85cd6253a763244e"},{["atomIDs"]={"94427:description:1-190","94427:objective:1-60","94427:completion:1-99"},["minimumStage"]=4,["questID"]=94427,["sourceHash"]="5abbdda6171afac990672ec346cf64859133d55d28ba509772aaaefc9f04e4f3"},{["atomIDs"]={"94435:description:1-166","94435:objective:1-54"},["minimumStage"]=4,["questID"]=94435,["sourceHash"]="89db2b9e0a48b09c1da49f575de8924b5895d189ed139f1557ea9561ac0301d9"},{["atomIDs"]={"94436:description:1-171","94436:objective:1-68","94436:completion:1-95"},["minimumStage"]=4,["questID"]=94436,["sourceHash"]="c8beb092836ab9b86e8c910d4ef50f8ed0bd54970fc7f368b3f0af2ac57e1a9b"},{["atomIDs"]={"94441:description:1-176","94441:objective:1-58","94441:completion:1-152"},["minimumStage"]=4,["questID"]=94441,["sourceHash"]="4195dac79024353b3f53be0a18e12f9fcc02713c5c818fe54cb8b1ee846d6293"},{["atomIDs"]={"95803:description:1-218","95803:objective:1-65"},["minimumStage"]=4,["questID"]=95803,["sourceHash"]="e7d2ae0036f7021fa8f928a3f93d61d9bbc44f5e6f1a011d4885fe43ff4b6295"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/91294",["title"]="Danitha Morr"},{["aliases"]={"Hilda the Breaker"},["category"]="figures",["fields"]={["context"]="Hilda the Breaker prepares trainees against a possible Scourge threat below Shadowvale. She asks for bones retaining reanimation magic so that the keep can understand a danger that remained hidden too long."},["gate"]="HISTORICAL",["id"]="npc-246389",["kind"]="figure",["npcIDs"]={246389},["questSourceProofs"]={{["atomIDs"]={"99152:description:1-219","99152:objective:1-62"},["minimumStage"]=4,["questID"]=99152,["sourceHash"]="5fc5b34bf62afbfe7798af6e834b6b1c49e57dcd6be90b17fa692968aa48ccff"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/99152",["title"]="Hilda the Breaker"},{["aliases"]={"Jorin Croge"},["category"]="figures",["fields"]={["context"]="Jorin Croge seeks building material for the restoration of Bandarion Keep. Distance from Undercity complicates supplies, making the root cellars of ruined Shadowvale a possible source of usable lumber."},["gate"]="HISTORICAL",["id"]="npc-246393",["kind"]="figure",["npcIDs"]={246393},["questSourceProofs"]={{["atomIDs"]={"91316:description:1-212","91316:objective:1-71","91316:completion:1-97"},["minimumStage"]=4,["questID"]=91316,["sourceHash"]="5614ce931b65a2e78930fb0c188e85835c10774421851ca82f00daaec807d77d"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/91316",["title"]="Jorin Croge"},{["aliases"]={"Lumina Windsinger"},["category"]="figures",["fields"]={["context"]="This observed form of Lumina Windsinger is the Windshaper captive at Fenris Keep. She identifies herself as shen'dorei rather than quel'dorei and says she traveled with Banon to study the elemental convergences of Arathi."},["gate"]="HISTORICAL",["id"]="npc-248755",["kind"]="figure",["npcIDs"]={248755},["questSourceProofs"]={{["atomIDs"]={"91861:description:1-157","91861:objective:1-70"},["minimumStage"]=4,["questID"]=91861,["sourceHash"]="624b234597dcc67673936062ea22ffbd46a2e47466d95f06f8759c65b0e91fb4"},{["atomIDs"]={"91862:description:1-218","91862:objective:1-79"},["minimumStage"]=4,["questID"]=91862,["sourceHash"]="c6377a3c50eb5c964f422c76d5c75171090f5e4344bc3ed5d26de3a87747caff"},{["atomIDs"]={"96204:description:1-172","96204:objective:1-54"},["minimumStage"]=4,["questID"]=96204,["sourceHash"]="f1f21ac9ae17d8b98f62a53f81bd3ac8601c95850c41677e33f57c1b7c3c8be1"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/91861",["title"]="Lumina Windsinger"},{["aliases"]={"Trevan Rol"},["category"]="figures",["fields"]={["context"]="Trevan Rol represents Danitha's interests at the Sepulcher. His account starts the search for the missing travelers, while his quiet respect for Ott's workmanship later helps obtain the blade needed against Old Fire-Eye."},["gate"]="HISTORICAL",["id"]="npc-248840",["kind"]="figure",["npcIDs"]={248840},["questSourceProofs"]={{["atomIDs"]={"91858:description:1-241","91858:objective:1-61"},["minimumStage"]=4,["questID"]=91858,["so