cada24dad9e3f"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/92679",["title"]="Aamelia Windfield"},{["aliases"]={"Vayn Moongaze"},["category"]="figures",["fields"]={["context"]="Vayn Moongaze seeks retaliation for the tragedy inflicted on the Nightclaw. Cultists' ears become both a paid commission and a measure of support through which an outsider may earn the enclave's trust."},["gate"]="HISTORICAL",["id"]="npc-254151",["kind"]="figure",["npcIDs"]={254151},["questSourceProofs"]={{["atomIDs"]={"93165:description:1-197","93165:objective:1-57"},["minimumStage"]=4,["questID"]=93165,["sourceHash"]="575bb52ecf51516cc957f76234bf17702fbe0a3359398ec8e7c48d9bb11fcf11"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/93165",["title"]="Vayn Moongaze"},{["aliases"]={"Urs'endris"},["category"]="figures",["fields"]={["context"]="Urs'endris is the great ursera spirit to whom Lotheluum sends druid learners. His teaching joins strength to painful responsibility when he asks that his maddened mate Ur'endra be stopped for the balance's sake."},["gate"]="HISTORICAL",["id"]="npc-255853",["kind"]="figure",["npcIDs"]={255853},["questSourceProofs"]={{["atomIDs"]={"94006:description:1-262","94006:objective:1-49"},["minimumStage"]=4,["questID"]=94006,["sourceHash"]="793f66b0ea6a25d0aa8474786222dce997f7a531994cc250d8e948db3381dc75"},{["atomIDs"]={"94638:description:1-224","94638:objective:1-66"},["minimumStage"]=4,["questID"]=94638,["sourceHash"]="a9add3f46476272a931d9c7f67409d7fcffbb1c42c15cc4dbee65f304adf3c55"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/94006",["title"]="Urs'endris"},{["aliases"]={"Dokimi"},["category"]="figures",["fields"]={["context"]="Dokimi enrolls associates at the Durotar Supply and Logistics outpost west of the Crossroads. She offers Merchant's Favor for help with compromised deliveries and prefers little additional paperwork."},["gate"]="HISTORICAL",["id"]="npc-256386",["kind"]="figure",["npcIDs"]={256386},["questSourceProofs"]={{["atomIDs"]={"98248:description:1-209","98248:objective:1-73"},["minimumStage"]=4,["questID"]=98248,["sourceHash"]="f0ead3e936d7b865dff3ada546195d2f3960d11342540620024dd195f38ab80f"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/98248",["title"]="Dokimi"},{["aliases"]={"Nyalah Brightfire"},["category"]="figures",["fields"]={["context"]="Nyalah Brightfire knows a narrow annual opportunity for harvesting Windsong Crawlers. Cult activity has kept her from the lake at the worst time, so another gatherer can preserve the season's catch."},["gate"]="HISTORICAL",["id"]="npc-257006",["kind"]="figure",["npcIDs"]={257006},["questSourceProofs"]={{["atomIDs"]={"93317:description:1-218","93317:objective:1-63"},["minimumStage"]=4,["questID"]=93317,["sourceHash"]="8b5272da953e9d72cf70640ab9d9d17438817394200759d884ef64a18967f019"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/93317",["title"]="Nyalah Brightfire"},{["aliases"]={"Messana Crestwind"},["category"]="figures",["fields"]={["context"]="Messana Crestwind supplies the mining instruction to which Raan refers aspiring campers. Her Lodestone lesson makes clear that a wilderness camp needs its fire before its specialized fixtures can be tested."},["gate"]="HISTORICAL",["id"]="npc-257022",["kind"]="figure",["npcIDs"]={257022},["questSourceProofs"]={{["atomIDs"]={"97970:description:1-210","97970:objective:1-64"},["minimumStage"]=4,["questID"]=97970,["sourceHash"]="18975630ecd8ff8d935e77bcbe44f903060a3e683cb3a6faaa458617743e04b9"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/97970",["title"]="Messana Crestwind"},{["aliases"]={"Missionary Jasaan"},["category"]="figures",["fields"]={["context"]="Missionary Jasaan receives recruits at Falaath Village and boasts that the Al'Aketh's strength gives form to the storm. His warnings about an important visitor at the inn reveal an opening for an investigator without explaining its result in advance."},["gate"]="HISTORICAL",["id"]="npc-257065",["kind"]="figure",["npcIDs"]={257065},["questSourceProofs"]={{["atomIDs"]={"92528:description:1-247","92528:objective:1-90"},["minimumStage"]=4,["questID"]=92528,["sourceHash"]="1a3b98043ea3af2b7dd5f273d3f190905f0ca96c08788133d3d706a85f9630de"},{["atomIDs"]={"92529:description:1-266","92529:objective:1-57"},["minimumStage"]=4,["questID"]=92529,["sourceHash"]="633db4e37bdcb21f12a329db3696d75d99c1583928c6d30deadfa04e76c45624"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/92528",["title"]="Missionary Jasaan"},{["aliases"]={"Tanis Alderwood"},["category"]="figures",["fields"]={["context"]="Tanis Alderwood is a beggar in Undercity whose wife needs cloth to hold her failing body together until apothecaries can help. A paladin's unasked-for kindness surprises him enough to make lasting gratitude part of the lesson."},["gate"]="HISTORICAL",["id"]="npc-257648",["kind"]="figure",["npcIDs"]={257648},["questSourceProofs"]={{["atomIDs"]={"94427:description:1-190","94427:objective:1-60","94427:completion:1-99"},["minimumStage"]=4,["questID"]=94427,["sourceHash"]="5abbdda6171afac990672ec346cf64859133d55d28ba509772aaaefc9f04e4f3"},{["atomIDs"]={"94434:description:1-187","94434:objective:1-56"},["minimumStage"]=4,["questID"]=94434,["sourceHash"]="6754ef11eaf4a4a11dd99798420969b4b59cab8e6708b181a21f36dad4b020da"},{["atomIDs"]={"94435:description:1-166","94435:objective:1-54"},["minimumStage"]=4,["questID"]=94435,["sourceHash"]="89db2b9e0a48b09c1da49f575de8924b5895d189ed139f1557ea9561ac0301d9"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/94427",["title"]="Tanis Alderwood"},{["aliases"]={"Deathguard Billmuth"},["category"]="figures",["fields"]={["context"]="Deathguard Billmuth seeks paladin aid for Falgan after a scouting mission goes wrong. Reluctance born of distrust gives way to gratitude when his friend's rescue also brings Scarlet attack plans to the Deathguard."},["gate"]="HISTORICAL",["id"]="npc-257655",["kind"]="figure",["npcIDs"]={257655},["questSourceProofs"]={{["atomIDs"]={"94436:description:1-171","94436:objective:1-68","94436:completion:1-95"},["minimumStage"]=4,["questID"]=94436,["sourceHash"]="c8beb092836ab9b86e8c910d4ef50f8ed0bd54970fc7f368b3f0af2ac57e1a9b"},{["atomIDs"]={"94438:description:1-252","94438:objective:1-72","94438:completion:1-136"},["minimumStage"]=4,["questID"]=94438,["sourceHash"]="9140f448f8c2ceaf690d6b6ba87ac040537d82087b60807693d1e220ff7f884e"},{["atomIDs"]={"94440:description:1-229","94440:objective:1-77","94440:completion:1-126"},["minimumStage"]=4,["questID"]=94440,["sourceHash"]="7969d8038b72581239d7e6a5efa7a0cc2d207b2c7b977ff121427afc0d81a8b3"},{["atomIDs"]={"94441:description:1-176","94441:objective:1-58","94441:completion:1-152"},["minimumStage"]=4,["questID"]=94441,["sourceHash"]="4195dac79024353b3f53be0a18e12f9fcc02713c5c818fe54cb8b1ee846d6293"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/94436",["title"]="Deathguard Billmuth"},{["aliases"]={"Deathguard Falgan"},["category"]="figures",["fields"]={["context"]="Deathguard Falgan scouts Scarlet activity with Billmuth at Venomweb Vale. His return through the Symbol of Life opens a chance to recover the enemy's orders, but that resurrection must not be presumed before the relevant lesson is completed."},["gate"]="HISTORICAL",["id"]="npc-257663",["kind"]="figure",["npcIDs"]={257663},["questSourceProofs"]={{["atomIDs"]={"94438:description:1-252","94438:objective:1-72","94438:completion:1-136"},["minimumStage"]=4,["questID"]=94438,["sourceHash"]="9140f448f8c2ceaf690d6b6ba87ac040537d82087b60807693d1e220ff7f884e"},{["atomIDs"]={"94440:description:1-229","94440:objective:1-77","94440:completion:1-126"},["minimumStage"]=4,["questID"]=94440,["sourceHash"]="7969d8038b72581239d7e6a5efa7a0cc2d207b2c7b977ff121427afc0d81a8b3"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/94438",["title"]="Deathguard Falgan"},{["aliases"]={"Elegael Thornpaw"},["category"]="figures",["fields"]={["context"]="Elegael Thornpaw survives the attack on the Shadowgale druids and urgently organizes aid for those left in the den. Healing supplies, the missing Jorel and evidence of betrayal pull her between care for survivors and anger at their attackers."},["gate"]="HISTORICAL",["id"]="npc-257944",["kind"]="figure",["npcIDs"]={257944},["questSourceProofs"]={{["atomIDs"]={"94484:description:1-252","94484:objective:1-74"},["minimumStage"]=4,["questID"]=94484,["sourceHash"]="1251adecd3205c9ed758e11ab257f3618fa4129578893b590ab74a0037339b91"},{["atomIDs"]={"94485:description:1-215","94485:objective:1-58"},["minimumStage"]=4,["questID"]=94485,["sourceHash"]="5c7de409fcb9dcb5a228abaca7f5a8773fa3a13e66961350d9a3fbb362c36cc7"},{["atomIDs"]={"94486:description:1-238","94486:objective:1-69"},["minimumStage"]=4,["questID"]=94486,["sourceHash"]="0a3cadb51f52b356cdc63e8b4c2ed67477ae40bfc75ac55b4923df4a80f18f33"},{["atomIDs"]={"94487:description:1-217","94487:objective:1-88"},["minimumStage"]=4,["questID"]=94487,["sourceHash"]="4b3b837869981a7c17b049ee805f158a8687e7c200363794878d1430fd9491fd"},{["atomIDs"]={"94488:description:1-197","94488:objective:1-73"},["minimumStage"]=4,["questID"]=94488,["sourceHash"]="5414dc1db2fc14dc944afcd4b1349fb95aaad94fd40c0415c42e88860904d53e"},{["atomIDs"]={"94489:description:1-185","94489:objective:1-62"},["minimumStage"]=4,["questID"]=94489,["sourceHash"]="79aeb0e8e8b235f77fa869f9ffcb5e75575a61c54b1884fee4581496e776a2e2"},{["atomIDs"]={"94490:description:1-213","94490:objective:1-74"},["minimumStage"]=4,["questID"]=94490,["sourceHash"]="67941919365ef6a334eec06e9565ec01bf885d81372f0acd2a4459605da45751"},{["atomIDs"]={"94491:description:1-204","94491:objective:1-68"},["minimumStage"]=4,["questID"]=94491,["sourceHash"]="7187b142272b71f45afb4f48024032416abdaa6e938d7690348e028fc42c8a8c"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/94484",["title"]="Elegael Thornpaw"},{["aliases"]={"Ealaane Nimbuswalker"},["category"]="figures",["fields"]={["context"]="Ealaane Nimbuswalker has fled Ban'aethal with other refugees. Requests for abandoned belongings and news of Resaan distinguish the shared loss of a home from the uncertain fate of the person she loves."},["gate"]="HISTORICAL",["id"]="npc-259012",["kind"]="figure",["npcIDs"]={259012},["questSourceProofs"]={{["atomIDs"]={"94896:description:1-211","94896:objective:1-78"},["minimumStage"]=4,["questID"]=94896,["sourceHash"]="eae96429816b73bf3a5c81af51ce912f6d875684d4ff28076520cbb4abc926ba"},{["atomIDs"]={"94897:description:1-209","94897:objective:1-57"},["minimumStage"]=4,["questID"]=94897,["sourceHash"]="e7af46cc1d03727d3237dd9d52945d69f2992ffc91e3a1a8ba519fd40cf3d535"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/94896",["title"]="Ealaane Nimbuswalker"},{["aliases"]={"Ephram Barbaro"},["category"]="figures",["fields"]={["context"]="Ephram Barbaro follows the trail of a cultist who escaped with a focusing-crystal fragment. His concern is what its remaining power may be doing beneath Shadowvale, whether raising undead or strengthening them."},["gate"]="HISTORICAL",["id"]="npc-259190",["kind"]="figure",["npcIDs"]={259190},["questSourceProofs"]={{["atomIDs"]={"99153:description:1-243","99153:objective:1-62"},["minimumStage"]=4,["questID"]=99153,["sourceHash"]="ad3028a3922a9f9e471d912a77abb0f70ea2bee1506ff840b1f8b5341ea71e5a"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/99153",["title"]="Ephram Barbaro"},{["aliases"]={"Deathguard Baldren"},["category"]="figures",["fields"]={["context"]="Deathguard Baldren witnessed gnolls bringing a large body to a pyre on Fenris Isle. His pessimism about the search exceeds what that sight alone proves, since he saw neither the elf nor another small corpse."},["gate"]="HISTORICAL",["id"]="npc-259611",["kind"]="figure",["npcIDs"]={259611},["questSourceProofs"]={{["atomIDs"]={"91859:description:1-214","91859:objective:1-50"},["minimumStage"]=4,["questID"]=91859,["sourceHash"]="e5fda2df523107e8a0ca2c86ad9687c3a2482c5fd9a8291f8092995b33c0833e"},{["atomIDs"]={"91860:description:1-161","91860:objective:1-75"},["minimumStage"]=4,["questID"]=91860,["sourceHash"]="62378f664505573eee0f02561e5651780cd583ca0eca79e60625eb7625a0b5fc"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/91859",["title"]="Deathguard Baldren"},{["aliases"]={"Lumina Windsinger"},["category"]="figures",["fields"]={["context"]="This observed form of Lumina Windsinger speaks at the Sepulcher after the escape from Fenris Keep. Her account of Banon's final struggle drives the hunt for Old Fire-Eye and the effort to make a weapon that can end it."},["gate"]="HISTORICAL",["id"]="npc-259620",["kind"]="figure",["npcIDs"]={259620},["questSourceProofs"]={{["atomIDs"]={"95034:description:1-217","95034:objective:1-45"},["minimumStage"]=4,["questID"]=95034,["sourceHash"]="7ec2c1d8fc207c303bb0a047ae47c01405c600f08f661c885ff928d8bac4c31b"},{["atomIDs"]={"95036:description:1-198","95036:objective:1-67"},["minimumStage"]=4,["questID"]=95036,["sourceHash"]="18105d060e78471aad3007fc0e5155cfe1e86ef2529d22972c53e44cedd495c2"},{["atomIDs"]={"95140:description:1-190","95140:objective:1-67"},["minimumStage"]=4,["questID"]=95140,["sourceHash"]="9ba94a7e0fa23a62f6626fd1df6677ffc411a2d8cf800f962eaf5c4d67bc1aac"},{["atomIDs"]={"96204:description:1-172","96204:objective:1-54"},["minimumStage"]=4,["questID"]=96204,["sourceHash"]="f1f21ac9ae17d8b98f62a53f81bd3ac8601c95850c41677e33f57c1b7c3c8be1"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/95034",["title"]="Lumina Windsinger"},{["aliases"]={"Ulric Frostveil"},["category"]="figures",["fields"]={["context"]="Ulric Frostveil knows how Kor Gems are used in paladin implements and where the Blackfathom naga keep them. The corruption he finds in a returned gem also interests him for research, putting his curiosity at odds with its intended commission."},["gate"]="HISTORICAL",["id"]="npc-259649",["kind"]="figure",["npcIDs"]={259649},["questSourceProofs"]={{["atomIDs"]={"95042:description:1-175","95042:objective:1-63"},["minimumStage"]=4,["questID"]=95042,["sourceHash"]="6990c857f2531f7af90d781fded65c6a6f64f88624bdec11be76d0d5403d097d"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/95042",["title"]="Ulric Frostveil"},{["aliases"]={"Raan Wildwind"},["category"]="figures",["fields"]={["context"]="Raan Wildwind teaches camping at Shen'dar Village. He begins with rest at a fire, then directs different trades toward particular furnishings rather than treating a campsite as one profession's work."},["gate"]="HISTORICAL",["id"]="npc-263664",["kind"]="figure",["npcIDs"]={263664},["questSourceProofs"]={{["atomIDs"]={"96101:description:1-207","96101:objective:1-76"},["minimumStage"]=4,["questID"]=96101,["sourceHash"]="2be0e59202ad10fb50f2594b2b947eb29e5f2b19e9c91d5ed85a9cc30fac34e7"},{["atomIDs"]={"96646:description:1-204","96646:objective:1-78"},["minimumStage"]=4,["questID"]=96646,["sourceHash"]="6bea712b79ee7fb8697fbb7af593624fa58091d9df46afef45fa7314469f7117"},{["atomIDs"]={"97965:description:1-183","97965:objective:1-93"},["minimumStage"]=4,["questID"]=97965,["sourceHash"]="788a6a800ba9292caa4f90bfa1d6ba2b8cf804ed83dde53c744a9cd3a2eef9c1"},{["atomIDs"]={"97969:description:1-184","97969:objective:1-97"},["minimumStage"]=4,["questID"]=97969,["sourceHash"]="ff9319bb454df7dfa10fddb1e9020e456b735ef7a39f4f271c38d20bad7837b7"},{["atomIDs"]={"97970:description:1-210","97970:objective:1-64"},["minimumStage"]=4,["questID"]=97970,["sourceHash"]="18975630ecd8ff8d935e77bcbe44f903060a3e683cb3a6faaa458617743e04b9"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/96101",["title"]="Raan Wildwind"},{["aliases"]={"Earthseer Farsen"},["category"]="figures",["fields"]={["context"]="Earthseer Farsen is visiting Dun Morogh from Aerie Peak when he notices the Dark Iron presence. His farsight and interpretation of an underground map move the investigation from visible spies toward the vaults beneath Ironforge."},["gate"]="HISTORICAL",["id"]="npc-264936",["kind"]="figure",["npcIDs"]={264936},["questSourceProofs"]={{["atomIDs"]={"96390:description:1-173","96390:objective:1-45"},["minimumStage"]=4,["questID"]=96390,["sourceHash"]="3caddb431254f653f19f1342acc7dc5a8989a0483d66d925f344e591fe8559e5"},{["atomIDs"]={"96391:description:1-163","96391:objective:1-52"},["minimumStage"]=4,["questID"]=96391,["sourceHash"]="e65d