"},["minimumStage"]=4,["questID"]=96604,["sourceHash"]="c8f56e66617bc1a682aa3e07f4c7a1e6f2a8da1e25360054e764a2dd9f86b63e"},{["atomIDs"]={"96652:description:1-150","96652:objective:1-46"},["minimumStage"]=4,["questID"]=96652,["sourceHash"]="ab7dc138fd78f9551e9e2a162d97bf17d97a80c8ebcd982e22f5f95c1e42273d"},{["atomIDs"]={"96655:description:1-148","96655:objective:1-59"},["minimumStage"]=4,["questID"]=96655,["sourceHash"]="f3cca62149bc0478a59855e029df9e491997f0dd5071dd0051b0af6e64eaf395"},{["atomIDs"]={"97908:description:1-181","97908:objective:1-60"},["minimumStage"]=4,["questID"]=97908,["sourceHash"]="c84d3497c36ec1ba550d28d4e29ef41acbe90ea73917eee056433e0e7d34f6dd"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/96604",["title"]="Brakk"},{["aliases"]={"Kaga Wildhoof"},["category"]="figures",["fields"]={["context"]="Kaga Wildhoof camps outside Bloodhoof Village and has helped Chief Hawkwind in the past. His supply gift reaches someone more interested in passing on camping knowledge than collecting a debt."},["gate"]="HISTORICAL",["id"]="npc-265810",["kind"]="figure",["npcIDs"]={265810},["questSourceProofs"]={{["atomIDs"]={"96605:description:1-175","96605:objective:1-76"},["minimumStage"]=4,["questID"]=96605,["sourceHash"]="8dacba607661cca6ef471c5de24561b4a7c4e581d6571fd729152c502c02ac26"},{["atomIDs"]={"96659:description:1-174","96659:objective:1-50"},["minimumStage"]=4,["questID"]=96659,["sourceHash"]="b136eebeafa21b45c2d38e1a618285609cc2c57098a60d0bc07684f254d2e08d"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/96605",["title"]="Kaga Wildhoof"},{["aliases"]={"Eleanor Shackleton"},["category"]="figures",["fields"]={["context"]="Eleanor Shackleton is an adventurer stopping near Brill before another wilderness journey. She answers suspicion of the Scarlet Crusade by describing her ordinary travels and inviting the visitor to learn camping."},["gate"]="HISTORICAL",["id"]="npc-265812",["kind"]="figure",["npcIDs"]={265812},["questSourceProofs"]={{["atomIDs"]={"96607:description:1-172","96607:objective:1-79"},["minimumStage"]=4,["questID"]=96607,["sourceHash"]="1d26ee41d9e0a0e1e2f5bfae17cfd65d50b77fa5941e932d145802984bfa1eda"},{["atomIDs"]={"96656:description:1-191","96656:objective:1-57"},["minimumStage"]=4,["questID"]=96656,["sourceHash"]="4f772dea1bff2675da4ff489eda6577635d02812a66b0137466e0c448ef64f09"},{["atomIDs"]={"96658:description:1-146","96658:objective:1-62"},["minimumStage"]=4,["questID"]=96658,["sourceHash"]="112179247ec2ea87c334bcddcafbe10d27ea6a1a344f5b329fc3beeaaf102eb6"},{["atomIDs"]={"97959:description:1-166","97959:objective:1-57"},["minimumStage"]=4,["questID"]=97959,["sourceHash"]="880f5dfea340767037b0caf375c46055db7df16693712cfbb3873d2d2dac5b68"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/96607",["title"]="Eleanor Shackleton"},{["aliases"]={"William Pickman"},["category"]="figures",["fields"]={["context"]="William Pickman teaches cooking in Brill along Eleanor's camping route. The lesson treats the fire as the campsite's foundation and further skill as a way to expand its possibilities."},["gate"]="HISTORICAL",["id"]="npc-265944",["kind"]="figure",["npcIDs"]={265944},["questSourceProofs"]={{["atomIDs"]={"96658:description:1-146","96658:objective:1-62"},["minimumStage"]=4,["questID"]=96658,["sourceHash"]="112179247ec2ea87c334bcddcafbe10d27ea6a1a344f5b329fc3beeaaf102eb6"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/96658",["title"]="William Pickman"},{["aliases"]={"Morbin Lightbane"},["category"]="figures",["fields"]={["context"]="Morbin Lightbane speaks of a Forsaken paladin's duty in terms of healing his people's bodies and enforcing the Dark Lady's will. His request for intact limbs from Lordaeron's ruins joins both purposes to Bandarion's remembered example."},["gate"]="HISTORICAL",["id"]="npc-266484",["kind"]="figure",["npcIDs"]={266484},["questSourceProofs"]={{["atomIDs"]={"92421:description:1-220","92421:objective:1-75"},["minimumStage"]=4,["questID"]=92421,["sourceHash"]="9149b74021e961763bff43b18748b6b92b7c417e4e80ebff08f84438105af524"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/92421",["title"]="Morbin Lightbane"},{["aliases"]={"Turroc"},["category"]="figures",["fields"]={["context"]="Turroc wants the fallen Horde warriors of Tiragarde remembered despite enemy occupation of their remains. Their recovered weapons can be displayed in honor where burial or recovery of the bodies is presently impossible."},["gate"]="HISTORICAL",["id"]="npc-266940",["kind"]="figure",["npcIDs"]={266940},["questSourceProofs"]={{["atomIDs"]={"96822:description:1-180","96822:objective:1-76"},["minimumStage"]=4,["questID"]=96822,["sourceHash"]="bef72e5cd3353fa655455a2c31e84d173c78b3772c657800037b2db1fbfc7715"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/96822",["title"]="Turroc"},{["aliases"]={"Leonid Barthalomew the Revered"},["category"]="figures",["fields"]={["context"]="Leonid Barthalomew remembers fighting the Scourge beside Danitha and Garek Bandarion. His visit to the keep reconnects Argent Dawn history with the new paladin fellowship, while correspondence with Glix preserves an older personal acquaintance."},["gate"]="HISTORICAL",["id"]="npc-267008",["kind"]="figure",["npcIDs"]={267008},["questSourceProofs"]={{["atomIDs"]={"96896:description:1-250","96896:objective:1-60"},["minimumStage"]=4,["questID"]=96896,["sourceHash"]="a