gory"]="figures",["fields"]={["context"]="Gur'ak believes the tales of Chol'aruk because he has encountered similar monstrous quilboars. He asks for tangible proof from Thorn Hill, promising that the slayer will retain the deed's credit even as the evidence supports his own story."},["gate"]="HISTORICAL",["id"]="npc-267310",["kind"]="figure",["npcIDs"]={267310},["questSourceProofs"]={{["atomIDs"]={"97003:description:1-227","97003:objective:1-66"},["minimumStage"]=4,["questID"]=97003,["sourceHash"]="9b83b65248091ee1584554824f1fbc4eccab47ea36d9fabbffbcac4408551c23"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/97003",["title"]="Gur'ak"},{["aliases"]={"Mountaineer Gretchen"},["category"]="figures",["fields"]={["context"]="Mountaineer Gretchen is trying to secure the mountain when Cornelius rushes into the Grizzled Den. Her subsequent report refuses to sacrifice more people for a cave she considers beyond safe recovery."},["gate"]="HISTORICAL",["id"]="npc-271546",["kind"]="figure",["npcIDs"]={271546},["questSourceProofs"]={{["atomIDs"]={"98319:description:1-189","98319:objective:1-53"},["minimumStage"]=4,["questID"]=98319,["sourceHash"]="94231d91a0c151bb3d9dfc69a2226fb6b05d00335b4f9e42d93ede07458ba1f7"},{["atomIDs"]={"98323:description:1-195","98323:objective:1-58"},["minimumStage"]=4,["questID"]=98323,["sourceHash"]="6a305335412a6d3427639618d7b7c73184fd20de33d08eb1d9cdc292577ee37d"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/98319",["title"]="Mountaineer Gretchen"},{["aliases"]={"Unfinished Abomination"},["category"]="figures",["fields"]={["context"]="The recorder calls this body an Unfinished Abomination; Faranell's account associates the recovered head with Othmar. Its panicked resistance is a stage-specific encounter, not a generic description of all abominations."},["gate"]="HISTORICAL",["id"]="npc-271613",["kind"]="figure",["npcIDs"]={271613},["questSourceProofs"]={{["atomIDs"]={"97289:description:1-249","97289:objective:1-63"},["minimumStage"]=4,["questID"]=97289,["sourceHash"]="21a925a59fc15b886d6efd2bbf27892462672287390739c8a963c19cee674373"},{["atomIDs"]={"97290:description:1-146","97290:objective:1-55"},["minimumStage"]=4,["questID"]=97290,["sourceHash"]="51d3f5763c9e1a730206d40a31d35c954b89dbca8f62953eede59cd00d2cee50"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/97289",["title"]="Unfinished Abomination"},{["aliases"]={"Glix Xizzix"},["category"]="figures",["fields"]={["context"]="Glix Xizzix receives Leonid's letter in Undercity's Trade Quarter. He has no enthusiasm for the tip promised on his behalf, but offers abandoned property from the lost and found to settle the courier's expectation."},["gate"]="HISTORICAL",["id"]="npc-272526",["kind"]="figure",["npcIDs"]={272526},["questSourceProofs"]={{["atomIDs"]={"98545:description:1-207","98545:objective:1-64"},["minimumStage"]=4,["questID"]=98545,["sourceHash"]="3bf643cd64be3b643ef86f59543c9703345bb53f2758cab8641ab764c9ce16aa"}},["questSourceProofsMode"]="ALL",["referenceStatus"]="PUBLISHER_REPORTED_BETA_CAPTURE_BUILD_UNREPORTED",["sourceURL"]="https://warcraftforever.games/quests/98545",["title"]="Glix Xizzix"},{["aliases"]={"Fendaal Windstone"},["category"]="figures",["fields"]={["context"]="Fendaal Windstone spots Al'Aketh assassins while patrolling the highlands border. He stays on watch while asking for help against the group and promises to include that assistance in his report to Valanaar."},["gate"]="HISTORICAL",["id"]="npc-273017",["kind"]="figure",["npcIDs"]={273017},["questSourceProofs"]={{["atomIDs"]={"98512:description:1-201","98512:objective:1-65"},["minimumStage"]=4,["questID"]=98512,["sourceHash"]="7c80e96327d80df59445ea92b75b