local titles={};for _,e in ipairs(D.entries) do titles[e.title]=e end
for _,row in ipairs(additions) do
 local old=titles[row.title]
 if old then
  -- Preserve curated history and its gate. Linking a known NPC ID does not
  -- replace a biography with a second independent character entry.
  old.npcIDs=old.npcIDs or {};local found=false
  for _,n in ipairs(old.npcIDs) do if n==row.npcIDs[1] then found=true end end
  if not found then old.npcIDs[#old.npcIDs+1]=row.npcIDs[1] end
 else D.entries[#D.entries+1]=row;titles[row.title]=row end
end
